import pm_guard_isolation as g
def px(v, context):
    return 'x' if v['x'] < 0 else None
def py(v, context):
    return 'y' if v['y'] < 0 else None

def factory():
    table = g.GuardTable([g.Guard('x', g.Invariant('/x', 'nonnegative'), 'x', px), g.Guard('y', g.Invariant('/y', 'nonnegative'), 'y', py)])
    context = None
    def check(value):
        table.require('x', value, context)
        table.require('y', value, context)
        return True
    return g.Case(table, check, context)

